"""Application errors rendered as stable JSON error responses."""

from __future__ import annotations


class APIError(Exception):
    def __init__(self, status_code: int, code: str, message: str) -> None:
        self.status_code = status_code
        self.code = code
        self.message = message
        super().__init__(message)


class NotFoundError(APIError):
    """A referenced dataset, schema version or field does not exist (404)."""

    def __init__(self, message: str) -> None:
        super().__init__(404, "not_found", message)


class ConflictError(APIError):
    """The request conflicts with already stored state (409)."""

    def __init__(self, message: str) -> None:
        super().__init__(409, "conflict", message)


class RequestInvalidError(APIError):
    """The request is structurally or semantically invalid (422)."""

    def __init__(self, message: str) -> None:
        super().__init__(422, "validation_error", message)

def require_dataset(conn: sqlite3.Connection, name: str, *, role: str = "Dataset") -> dict:
    dataset = get_dataset_by_name(conn, name)
    if dataset is None:
        raise NotFoundError(f"{role} '{name}' does not exist")
    return dataset


def create_dataset(conn: sqlite3.Connection, name: str, description: str) -> dict:
    clean_name = name.strip()
    if not clean_name:
        raise RequestInvalidError("Dataset name must not be empty")

    created_at = utc_now_iso()
    try:
        cursor = conn.execute(
            "INSERT INTO datasets (name, description, created_at) VALUES (?, ?, ?)",
            (clean_name, description, created_at),
        )
    except sqlite3.IntegrityError as exc:
        raise ConflictError(f"Dataset '{clean_name}' already exists") from exc
    row = conn.execute(
        "SELECT id, name, description, created_at FROM datasets WHERE id = ?",
        (cursor.lastrowid,),
    ).fetchone()
    return _row_to_dict(row)

    dataset = require_dataset(conn, dataset_name)

    # Any body bytes are rejected, including a purely whitespace or
    # single-space body; ``if body`` (rather than a stripped check) keeps
    # those a 422, matching the processing audit export.
    if body:
        raise RequestInvalidError(
            "The quality gate export endpoint does not accept a request body"
        )
    if query_keys:
        raise RequestInvalidError(
            "The quality gate export endpoint does not accept query parameters"
        )

    version_rows = conn.execute(
        "SELECT * FROM schema_versions "
        "WHERE dataset_id = ? ORDER BY version ASC",
        (dataset["id"],),
    ).fetchall()

    versions: list[dict] = []
    for version_row in version_rows:
        evaluation_rows, anomaly_rows = _quality_gate_records(
            conn, version_row["id"]
        )
        gate = _quality_gate_result(
            dataset, version_row, evaluation_rows, anomaly_rows
        )
        versions.append(
            {
                "version": version_row["version"],
                "verdict": gate["verdict"],
                "reason_count": len(gate["reasons"]),
                "violation_row_count": (
                    evaluation_rows[-1]["violation_row_count"]
                    if evaluation_rows
                    else None
                ),
            }
        )

    totals = {
        "version_count": len(versions),
        "failed_count": sum(
            1 for version in versions if version["verdict"] == "fail"
        ),
        "reason_count": sum(version["reason_count"] for version in versions),
        "violation_row_count": sum(
            version["violation_row_count"] or 0 for version in versions
        ),
    }
    return {"dataset": dataset["name"], "versions": versions, "totals": totals}


